       @Omega.SemanticOmegaSelection MF FI FO ->
       forall (A B R1 R2 : Type) (RR : R1 -> R2 -> Prop) (RS : A -> B -> Prop)
         (t1 : PTreeDefinition.ptree E MN R1) (t2 : PTreeDefinition.ptree E MN R2)
         (k1 : R1 -> PTreeDefinition.ptree E MN A) (k2 : R2 -> PTreeDefinition.ptree E MN B),
       @PEutt.peutt E MN MF FI FC MX FO R1 R2 RR t1 t2 ->
       (forall (r1 : R1) (r2 : R2),
        RR r1 r2 -> @PEutt.peutt E MN MF FI FC MX FO A B RS (k1 r1) (k2 r2)) ->
       @PEutt.peutt E MN MF FI FC MX FO A B RS (@PTreeDefinition.PTree.bind E MN R1 A t1 k1)
         (@PTreeDefinition.PTree.bind E MN R2 B t2 k2)

