@PEutt.peutt_bind_cofinal
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       (forall (A R : Type) (t : PTreeDefinition.ptree E MN A)
          (k : A -> PTreeDefinition.ptree E MN R),
        @PTreeKernel.ptree_bind_cofinal E MN MF FI MX FO A R t k) ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       forall (A B R1 R2 : Type) (RR : R1 -> R2 -> Prop) (RS : A -> B -> Prop)
         (t1 : PTreeDefinition.ptree E MN R1) (t2 : PTreeDefinition.ptree E MN R2)
         (k1 : R1 -> PTreeDefinition.ptree E MN A) (k2 : R2 -> PTreeDefinition.ptree E MN B),
       @PEutt.peutt E MN MF FI FC MX FO R1 R2 RR t1 t2 ->
       (forall (r1 : R1) (r2 : R2),
        RR r1 r2 -> @PEutt.peutt E MN MF FI FC MX FO A B RS (k1 r1) (k2 r2)) ->
       @PEutt.peutt E MN MF FI FC MX FO A B RS (@PTreeDefinition.PTree.bind E MN R1 A t1 k1)
         (@PTreeDefinition.PTree.bind E MN R2 B t2 k2)

@PEutt.peutt_coinduction_upto_bind
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       (forall (A R : Type) (t : PTreeDefinition.ptree E MN A)
          (k : A -> PTreeDefinition.ptree E MN R),
        @PTreeKernel.ptree_bind_cofinal E MN MF FI MX FO A R t k) ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       forall (A B : Type) (RR0 : A -> B -> Prop)
         (sim : PTreeDefinition.ptreeF E MN A (PTreeDefinition.ptree E MN A) ->
                PTreeDefinition.ptreeF E MN B (PTreeDefinition.ptree E MN B) -> Prop),
       (forall (s1 : PTreeDefinition.ptreeF E MN A (PTreeDefinition.ptree E MN A))
          (s2 : PTreeDefinition.ptreeF E MN B (PTreeDefinition.ptree E MN B)),
        sim s1 s2 ->
        @StableHittingRelation.stable_hitting_match MF FI FO
          (PTreeDefinition.ptreeF E MN A (PTreeDefinition.ptree E MN A))
          (PTreeDefinition.ptreeF E MN B (PTreeDefinition.ptree E MN B))
          (UnifiedFrontier.stable_head E MN A) (UnifiedFrontier.stable_head E MN B)
          (@PTreeKernel.ptree_primitive_kernel E MN MF FI MX A)
          (@PTreeKernel.ptree_primitive_kernel E MN MF FI MX B)
          (@PEutt.ptree_stable_head_rel E MN A B RR0)
          (@PEutt.bind_upto_closure E MN MF FI FC MX FO A B RR0 sim) s1 s2) ->
       forall (t1 : PTreeDefinition.ptree E MN A) (t2 : PTreeDefinition.ptree E MN B),
       sim (@PTreeDefinition.observe E MN A t1) (@PTreeDefinition.observe E MN B t2) ->
       @PEutt.peutt E MN MF FI FC MX FO A B RR0 t1 t2

